package main
import("fmt";"slices";"srpg/internal/content")
func main(){ d,e:=content.Load("./assets/data"); if e!=nil{panic(e)}; for _,id:=range []string{"chengyu","liru","shenpei","huangfusong","xusi","fangong","xunyou","fazheng","xiahouyuan","luxun","liupi","liubei","yujin"} { c:=d.Characters[id]; p:=d.Classes[c.Class].AllPool();fmt.Printf("%s (%s) plan:",c.Name,d.Classes[c.Class].Name); for _,t:=range c.Traits { fmt.Printf(" %s",d.Traits[t].Name);if slices.Contains(p,t){fmt.Print("[병종중복]")} };for t,l:=range c.TraitAt{fmt.Printf(" %s@%d",d.Traits[t].Name,l);if slices.Contains(p,t){fmt.Print("[병종중복]")}};fmt.Println();for _,l:=range []int{1,16,24,25,31,46,49,50,61}{cl:=d.PromotedAt(id,c.Class,l); ts:=d.PlannedTraits(id,cl,l,nil);fmt.Printf(" %d %s %d:",l,d.Classes[cl].Name,len(ts));for _,t:=range ts {fmt.Printf(" %s",d.Traits[t].Name)};fmt.Println()}};c:=d.Classes["repeating_crossbow"];fmt.Print("연노병:");for _,p:=range c.Plan{fmt.Printf(" %d:%s",p.Level,d.Traits[p.Trait].Name)};fmt.Println() }
